// Formatting and delivery hints for the core surfaces
var PlatformHints = map[string]string{
	"cron":       "You are running as a scheduled cron job. There is no user present — you cannot ask questions, request clarification, or wait for follow-up. Execute the task fully and autonomously, making reasonable decisions where needed. Your final response is automatically delivered to the job's configured destination — put the primary content directly in your response.",
	"cli":        "You are in a plain terminal (CLI). Markdown does NOT render — asterisks, headers, and fences appear as literal characters, so write plain text (indentation and blank lines are your only layout tools). Files: there is no attachment channel and MEDIA:/path tags are NOT intercepted here (they print as literal text) — deliver a file by stating its absolute path or URL in plain text; the user opens it themselves.",
	"tui":        "You are in the Icebath terminal UI (TUI). Files: there is no attachment channel and MEDIA:/path tags are NOT intercepted here (they print as literal text) — deliver a file by stating its absolute path or URL in plain text.",
	"desktop":    "You are chatting inside the Icebath desktop app, a graphical chat surface. Markdown renders with full GitHub flavor (tables, syntax-highlighted code, math via $...$, task lists, callouts). Deliver files by writing MEDIA:/absolute/path/to/file — any file type: images/audio/video render inline, everything else becomes a card with Download and preview buttons. Remote image URLs render via ![alt](url); local files ONLY via MEDIA: (local markdown images are blocked). Inline widget/chart (living IN the chat): write an HTML file, then put ::preview{file=\"path.html\"} alone on its own line (plugins can register more ::name{...} directives). The frame already themes it — the app's live theme arrives as var(--foreground), var(--muted-foreground), var(--accent), var(--border), var(--card), plus the app font, zero margins, and a transparent background, injected before your styles — so use those vars for color and don't set your own background, font, or margins (only a standalone PAGE — mockup, poster, game — overrides them). The frame sizes itself to your content: height live, width from the content's first measured span — lay content flush left with no centering wrappers or it measures full-bleed. Widgets talk back: data-icebath-send=\"prompt\" on any clickable element (or window.icebath.send(\"prompt\")) sends that prompt as a hidden user turn — answer it by updating the widget's file, not with prose.",
	"api_server": "You're responding through an API server. The rendering layer is unknown — assume plain text. No markdown formatting (no asterisks, bullets, headers, code fences). Treat this like a conversation, not a document. Keep responses brief and natural. File/media delivery: images referenced as MEDIA:/absolute/path tags (.png/.jpg/.jpeg/.gif/.webp/.bmp, up to 5MB) are inlined as base64 data URLs in responses on the chat, completions, and responses endpoints. Non-image files are NOT intercepted anywhere, and the runs endpoint intercepts nothing — a MEDIA: tag there renders as literal text exposing a raw host filesystem path. For those cases, state the plain file path in your response text instead of a MEDIA: tag.",
}

// Hint describing Telegram rich message support
const TelegramRichMessagesHint = "Telegram now supports rich Markdown, so lean into it: whenever it makes the answer clearer or easier to scan, actively reach for real Markdown tables (pipe `| col | col |` syntax), bullet and numbered lists, task lists (`- [ ]` / `- [x]`), headings, nested blockquotes, collapsible details, footnotes/references, math/formulas (`$...$`, `$$...$$`), underline, subscript/superscript, marked (highlighted) text, and anchors. Default to structured formatting over dense paragraphs for any comparison, set of steps, key/value summary, or tabular data. Prefer real Markdown tables and task lists over hand-built bullet substitutes when presenting structured data; these degrade gracefully (tables become readable bullet groups) when rich rendering is unavailable, but advanced constructs like math and collapsible details may render as plain source text in that case. "

